from abc import ABCMeta, abstractmethod
from .builder import Builder
from .bip.airphone import AirphoneBipCollectorConfigurator
import six
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@six.add_metaclass(ABCMeta)
class UeBuilder(Builder):
    ne_type = "ue"

    @abstractmethod
    def add_bip(self, ne_log_name, ne_log_configuration):
        pass


class AirphoneBuilder(
        AirphoneBipCollectorConfigurator,
        UeBuilder):

    def __init__(
            self,
            tl_config_information_provider,
            airphone_information_provider,
            **kwargs):
        super(AirphoneBuilder, self).__init__(**kwargs)
        self.tl_config_information_provider = tl_config_information_provider
        self.airphone_information_provider = airphone_information_provider

    def dummy_collector(self, ne_log_name):
        warning_msg = f"Log {ne_log_name} not implemented for airphone"
        logger.debug(warning_msg)
        self._collector_configuration_data.append(
            {
                'name': ne_log_name,
                'type': 'log_collection_dummy'})

    def add_syslog(self, ne_log_name, ne_log_configuration):
        self.dummy_collector(ne_log_name)

    def add_emil(self, ne_log_name, ne_log_configuration):
        self.dummy_collector(ne_log_name)

    def add_protocols(self, ne_log_name, ne_log_configuration):
        self.dummy_collector(ne_log_name)

    def add_snapshot(self, ne_log_name, ne_log_configuration):
        self.dummy_collector(ne_log_name)

    def add_pmcounters(self, ne_log_name, ne_log_configuration):
        self.dummy_collector(ne_log_name)

    def add_ocp(self, ne_log_name, ne_log_configuration):
        self.dummy_collector(ne_log_name)

    def add_uplane_trace(self, ne_log_name, ne_log_configuration):
        self.dummy_collector(ne_log_name)
